1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
5	import org.springframework.samples.petclinic.rest.escalation.InvalidPostcodeException;
6	import org.springframework.samples.petclinic.util.PostcodeRange;
7	
8	/**
9	 * Validates the optional owner postcode. Postcode is optional, so a null or blank value
10	 * is left untouched; when present it must be exactly 4 digits and — for a city with a
11	 * known region — fall within that region's range (otherwise a 400 via
12	 * {@link InvalidPostcodeException}). A city with no known region accepts any 4-digit
13	 * postcode. The value is stored and returned unchanged.
14	 */
15	public class ValidateOwnerPostcode {
16	
17	    public void service(@Val OwnerFieldsDto request) throws InvalidPostcodeException {
18	        String postcode = request.getPostcode();
19	        if (postcode == null || postcode.isBlank()) {
20	            return;
21	        }
22	        if (!postcode.matches("[0-9]{4}")) {
23	            throw new InvalidPostcodeException(postcode, "must be exactly 4 digits");
24	        }
25	        if (!PostcodeRange.isValidForCity(request.getCity(), postcode)) {
26	            throw new InvalidPostcodeException(postcode,
27	                "out of range for city '" + request.getCity() + "'");
28	        }
29	    }
30	}
