6	/**
7	 * Stamps a newly built owner with its deterministic {@code householdId} — the first 12 hex
8	 * characters of SHA-256 over its normalized last name and postcode (see
9	 * {@link Households#householdId}). Because the id is derived purely from
10	 * {@code (lastName, postcode)}, every owner in the same household resolves to the same id
11	 * automatically, with no explicit linking; an owner without a postcode has no household
12	 * ({@code householdId} unset). Runs after {@link BuildOwner} (so the owner's fields are
13	 * set) and before {@link SaveOwner} (so the id is stored and returned), mutating the built
14	 * owner in place.
15	 */
16	public class AssignHousehold {
17	
18	    public void service(@Val Owner owner) {
19	        owner.setHouseholdId(Households.householdId(owner.getLastName(), owner.getPostcode()));
20	    }
21	}
