1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.Locale;
4	
5	import org.springframework.samples.petclinic.model.Owner;
6	import org.springframework.samples.petclinic.repository.OwnerRepository;
7	import org.springframework.samples.petclinic.util.Sha256;
8	
9	/**
10	 * Derives the household an owner belongs to. A household is keyed on
11	 * {@code (lastName, postcode)}: its {@code householdId} is the first 12 hex characters of
12	 * SHA-256 over {@code normalizedLastName + '|' + postcode}, so two owners with the same
13	 * last name and postcode deterministically resolve to the same id without any explicit
14	 * linking. Used to detect household duplicates ({@link EnsureUniqueIdentity}), to stamp
15	 * each owner with its id ({@link AssignHousehold}) and to size the household
16	 * ({@link AssignHouseholdSize}).
17	 */
18	final class Households {
19	
20	    private Households() {
21	    }
22	
23	    /**
24	     * The household id for the given last name and postcode: the first 12 hex characters of
25	     * SHA-256 over the normalized last name and postcode. Returns null when the postcode is
26	     * blank, since without a postcode there is no household key.
27	     */
28	    static String householdId(String lastName, String postcode) {
29	        if (postcode == null || postcode.isBlank()) {
30	            return null;
31	        }
32	        return Sha256.hex(normalizeName(lastName) + '|' + postcode).substring(0, 12);
33	    }
34	
35	    /** How many existing owners already carry the given household id (0 when it is null). */
36	    static int memberCount(OwnerRepository repository, String householdId) {
37	        if (householdId == null) {
38	            return 0;
39	        }
40	        int count = 0;
41	        for (Owner owner : repository.findAll()) {
42	            if (householdId.equals(owner.getHouseholdId())) {
43	                count++;
44	            }
45	        }
46	        return count;
47	    }
48	
49	    /** Case-fold and collapse whitespace so trivial spacing/casing differences still match. */
50	    private static String normalizeName(String value) {
51	        return value == null ? "" : value.strip().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
52	    }
53	}
