1	package org.springframework.samples.petclinic.util;
2	
3	import java.nio.charset.StandardCharsets;
4	import java.security.MessageDigest;
5	import java.security.NoSuchAlgorithmException;
6	
7	/**
8	 * Shared SHA-256 hex digest, so the several identity values derived from a hash (the
9	 * customer code's {@code HASH8} segment and the household id) all agree on the algorithm
10	 * and encoding instead of each carrying their own copy.
11	 */
12	public final class Sha256 {
13	
14	    private Sha256() {
15	    }
16	
17	    /** The lower-case hex SHA-256 of the UTF-8 bytes of {@code value}. */
18	    public static String hex(String value) {
19	        try {
20	            byte[] digest = MessageDigest.getInstance("SHA-256").digest(value.getBytes(StandardCharsets.UTF_8));
21	            StringBuilder hex = new StringBuilder(digest.length * 2);
22	            for (byte b : digest) {
23	                hex.append(String.format("%02x", b));
24	            }
25	            return hex.toString();
26	        }
27	        catch (NoSuchAlgorithmException ex) {
28	            throw new IllegalStateException("SHA-256 not available", ex);
29	        }
30	    }
31	}
