1	package org.springframework.samples.petclinic.util;
2	
3	import org.springframework.samples.petclinic.model.Owner;
4	
5	/**
6	 * The canonical region ("locality") of an owner: the region derived from its postcode
7	 * first (see {@link PostcodeRange#regionOf(String)}), falling back to the city-to-region
8	 * table when the postcode is absent or in no known range, or {@link CityRegion#UNKNOWN}
9	 * for a city not in the table.
10	 *
11	 * <p>This region is the {@code REGION} segment of the owner's customer-code identity (see
12	 * {@link CustomerCode}); the identity is built from it on creation and the locality read
13	 * back off it, so there is one region concept rather than two derivations that could drift.
14	 */
15	public final class OwnerRegion {
16	
17	    private OwnerRegion() {
18	    }
19	
20	    /** The region for the given owner, derived from its postcode then its city. */
21	    public static String of(Owner owner) {
22	        String byPostcode = PostcodeRange.regionOf(owner.getPostcode());
23	        return byPostcode != null ? byPostcode : CityRegion.localityOf(owner.getCity());
24	    }
25	}
