4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.repository.OwnerRepository;
6	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
7	import org.springframework.samples.petclinic.rest.escalation.DuplicateIdentityException;
8	
9	/**
10	 * The duplicate block: rejects a create whose {@code (lastName, postcode)} household —
11	 * identified by its deterministic {@code householdId} (see {@link Households#householdId})
12	 * — is already occupied by an existing owner, as a 409 via
13	 * {@link DuplicateIdentityException}. Because the household is keyed on last name and
14	 * postcode, a second owner at the same one is a household duplicate.
15	 *
16	 * <p>A request that opts in with {@code sharesHousehold=true} bypasses the block: it is a
17	 * declared member of that household and is created (see {@link AssignPossibleDuplicate},
18	 * which also leaves a declared member unflagged). A request with no postcode has no
19	 * household key and cannot collide.
20	 *
21	 * <p>Runs before {@link BuildOwner}, so a collision is caught before any owner is built or
22	 * saved.
23	 */
24	public class EnsureUniqueIdentity {
25	
26	    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
27	            throws DuplicateIdentityException {
28	        if (Boolean.TRUE.equals(request.getSharesHousehold())) {
29	            return;
30	        }
31	        String householdId = Households.householdId(request.getLastName(), request.getPostcode());
32	        if (householdId == null) {
33	            return;
34	        }
35	        for (Owner existing : ownerRepository.findAll()) {
36	            if (householdId.equals(existing.getHouseholdId())) {
37	                throw new DuplicateIdentityException(householdId);
38	            }
39	        }
40	    }
41	}
